def floyd_warshall(weights: list[list[int]]) -> list[list[int]]:
    """Shortest distance between every pair of nodes; NO_EDGE where no path exists."""
    n: int = len(weights)
    dist: list[list[int]] = []
    for i in range(n):
        row: list[int] = []
        for j in range(n):
            row.append(weights[i][j])
        dist.append(row)
    for k in range(n):
        for i in range(n):
            dik: int = dist[i][k]
            if dik >= NO_EDGE:
                continue
            for j in range(n):
                alt: int = dik + dist[k][j]
                if alt < dist[i][j]:
                    dist[i][j] = alt
    return dist

